def S(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check(n):
    for k in range(38):
        if S(n + k) % 11 == 0:
            return False
    return True

def find_smallest():
    n = 1
    while n < 1000000:
        if check(n):
            return n
        n += 1
    return None

print(find_smallest())
